    for i in range(n0):
        pi, hi, di = player[i]
        if pi not in floor_hp:
            floor_hp[pi] = hi
        else:
            floor_hp[pi] = max(floor_hp[pi], hi)
    for i in range(n0):
        pi, hi, di = player[i]
        if di == 'U':
            for j in range(pi + 1, max(floor_hp.keys()) + 1):
