                    if floor_hp[j] > hi:
                        floor_hp[j] -= 1
                    elif floor_hp[j] == hi:
                        del floor_hp[j]
                        break
        else:
            for j in range(pi - 1, min(floor_hp.keys()) - 1, -1):
